#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    string arrangeWords(string text) {
        stringstream ss(text);
        vector<string> words;
        string word;
        while (ss >> word) words.push_back(word);

        words[0][0] = static_cast<char>(tolower(static_cast<unsigned char>(words[0][0])));
        stable_sort(words.begin(), words.end(), [](const string& a, const string& b) {
            return a.size() < b.size();
        });
        words[0][0] = static_cast<char>(toupper(static_cast<unsigned char>(words[0][0])));

        string result;
        for (size_t i = 0; i < words.size(); ++i) {
            if (i) result += ' ';
            result += words[i];
        }
        return result;
    }
};

