#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct Word { char *text; size_t len; size_t index; };

static int word_cmp(const void *pa, const void *pb) {
    const struct Word *a = (const struct Word *)pa;
    const struct Word *b = (const struct Word *)pb;
    if (a->len < b->len) return -1;
    if (a->len > b->len) return 1;
    if (a->index < b->index) return -1;
    if (a->index > b->index) return 1;
    return 0;
}

static char *dup_range(const char *start, size_t len) {
    char *out = (char *)malloc(len + 1);
    if (!out) return NULL;
    memcpy(out, start, len);
    out[len] = '\0';
    return out;
}

static char *arrangeWords(char *text) {
    size_t capacity = 16, count = 0;
    struct Word *words = (struct Word *)malloc(capacity * sizeof(struct Word));
    if (!words) return NULL;
    char *p = text;
    while (*p) {
        char *start = p;
        while (*p && *p != ' ') ++p;
        size_t len = (size_t)(p - start);
        if (count == capacity) {
            capacity *= 2;
            struct Word *tmp = (struct Word *)realloc(words, capacity * sizeof(struct Word));
            if (!tmp) { free(words); return NULL; }
            words = tmp;
        }
        words[count].text = dup_range(start, len);
        if (!words[count].text) { free(words); return NULL; }
        words[count].len = len;
        words[count].index = count++;
        if (*p == ' ') ++p;
    }
    if (count == 0) { free(words); return NULL; }
    for (size_t i = 0; words[0].text[i]; ++i)
        if (words[0].text[i] >= 'A' && words[0].text[i] <= 'Z')
            words[0].text[i] = (char)(words[0].text[i] - 'A' + 'a');
    qsort(words, count, sizeof(struct Word), word_cmp);
    if (words[0].text[0] >= 'a' && words[0].text[0] <= 'z')
        words[0].text[0] = (char)(words[0].text[0] - 'a' + 'A');
    size_t total = count - 1;
    for (size_t i = 0; i < count; ++i) total += words[i].len;
    char *result = (char *)malloc(total + 1);
    if (!result) { for (size_t i=0;i<count;++i) free(words[i].text); free(words); return NULL; }
    char *out = result;
    for (size_t i = 0; i < count; ++i) {
        if (i) *out++ = ' ';
        memcpy(out, words[i].text, words[i].len);
        out += words[i].len;
        free(words[i].text);
    }
    *out = '\0';
    free(words);
    return result;
}

